package com.slotmind.repository; import com.slotmind.entity.*; import com.slotmind.enums.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface SlotRepository extends JpaRepository<Slot,String> { List<Slot> findByStatusAndStartTimeAfterOrderByStartTimeAsc(SlotStatus status, java.time.Instant time); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from Slot s where s.id=:id") Optional<Slot> lockById(String id); }